function alignShortages(r){
 const total=1020;
 r.querySelectorAll('#x19g-board-edit .msd-day').forEach(day=>{
  const grid=day.querySelector('.msd-slot-grid');if(!grid)return;
  [...day.querySelectorAll(':scope > .msd-shortage-card')].forEach(card=>{
   const text=card.querySelector('.msd-shortage-time')?.textContent||'';
   const hit=text.match(/(\d{2}:\d{2}).*?(\d{2}:\d{2})/);if(!hit)return;
   const mm=v=>{const [h,m]=v.split(':').map(Number);return h*60+m};
   const start=Math.max(300,Math.min(1320,mm(hit[1]))),end=Math.max(start+30,Math.min(1320,mm(hit[2])));
   const top=((start-300)/total)*100,height=Math.max(8,((end-start)/total)*100);
   card.classList.add('x19g-inline-shortage');card.style.top=top+'%';card.style.height=height+'%';grid.appendChild(card);
  });
 });
}
